#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Given a non‐empty Vec of i8’s, returns the index of its first minimum.
    /// 
    /// Requires:
    ///   - a.len() > 0
    /// Ensures:
    ///   - result < a.len()
    ///   - for all j < a.len(): a[result] <= a[j]
    ///   - for all j < result: a[j] > a[result]
    pub fn nanargmin(a: Vec<i8>) -> (result: usize)
        requires a.len() > 0
        ensures result < a.len()
        ensures forall |j: usize| j < a.len() ==> a[result] <= a[j]
        ensures forall |j: usize| j < result ==> a[j] > a[result]
    {
        let len = a.len();
        let mut min_idx: usize = 0;
        let mut i: usize = 1;

        // Loop from i=1 .. len.  At each step:
        //   - 1 <= i <= len
        //   - min_idx < i
        //   - a[min_idx] is minimal over [0, i)
        //   - no earlier position k<i has value <= a[min_idx]
        while i < len
            invariant i <= len
            invariant 1 <= i
            invariant min_idx < i
            invariant forall |k: usize| k < i ==> a[min_idx] <= a[k]
            invariant forall |k: usize| k < min_idx ==> a[k] > a[min_idx]
            decreases len - i
        {
            // If we find a strictly smaller element at i, update min_idx.
            // This preserves both invariants:
            //   - new min_idx < i+1
            //   - new a[min_idx] is ≤ everything in [0,i], and strictly
            //     dominates all k < min_idx
            if a[i] < a[min_idx] {
                min_idx = i;
            }
            i = i + 1;
        }

        // At exit, i == len, so
        //   min_idx < len
        //   ∀ k < len: a[min_idx] ≤ a[k]
        //   ∀ k < min_idx: a[k] > a[min_idx]
        result = min_idx;
    }

}